fn main() {
    let os = std::env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let arch = std::env::var("CARGO_CFG_TARGET_ARCH").unwrap_or_default();
    assert!(os != "macos" || arch == "aarch64", "Lyrical Sync supports Apple Silicon Macs only; Intel macOS is unsupported.");
    
    // Watch for changes in permissions and capabilities directories
    println!("cargo:rerun-if-changed=permissions");
    println!("cargo:rerun-if-changed=capabilities");
    
    // Commands that need app-command permissions autogenerated
    let commands = &[
        "read_lrc_file",
        "write_lrc_file",
        "read_audio_file",
        "validate_audio_file",
        "get_audio_file_info",
        "decode_audio_to_wav",
        "read_audio_metadata",
        "write_batch_output",
        "set_models_dir_override",
        "get_models_dir",
        "check_model_files",
        "begin_model_download",
        "download_model",
        "cancel_model_download",
        "delete_model_files",
        "get_python_env_info",
        "download_embedded_python",
        "install_python_packages",
        "run_alignment",
        "cancel_alignment",
        "start_oauth_listener",
        "cancel_oauth_listener",
        "exchange_spotify_token",
        "refresh_spotify_token",
        "save_refresh_token",
        "load_refresh_token",
        "clear_refresh_token",
        "check_ytdlp",
        "download_ytdlp",
        "cancel_ytdlp_install",
        "ytdlp_load_audio",
        "cancel_ytdlp_load",
        "lrclib_publish",
        "cancel_lrclib_publish",
        "get_now_playing",
        "now_playing_toggle_play_pause",
        "now_playing_seek",
        "create_security_bookmark",
        "resolve_security_bookmark",
        "ytdlp_load_audio_url",
    ];
    
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .capabilities_path_pattern("./capabilities/**/*")
            .app_manifest(tauri_build::AppManifest::new().commands(commands))
    ).unwrap()
}
